(r, big) => {
  const nd = v => ({ v, L: null, R: null });
  const put = (t, x, b) => { if (!t) return x; let c = t; for (;;) { const k = r.bool(b) ? "L" : "R"; if (!c[k]) { c[k] = x; return t; } c = c[k]; } };
  const rnd = (n, V, b) => { let t = null; for (let i = 0; i < n; i++) t = put(t, nd(V()), b); return t; };
  const deep = (len, n, V) => { const t = nd(V()); let c = t; for (let i = 1; i < len; i++) { const k = r.bool() ? "L" : "R"; c[k] = nd(V()); c = c[k]; } for (let i = len; i < n; i++) put(c, nd(V()), 0.5); return t; };
  const ser = t => { const o = [], q = [t]; for (let i = 0; i < q.length; i++) { const x = q[i]; if (x) { o.push(x.v); q.push(x.L, x.R); } else o.push(null); } while (o.length && o[o.length - 1] === null) o.pop(); return o; };
  const size = t => t ? 1 + size(t.L) + size(t.R) : 0;
  const copy = t => JSON.parse(JSON.stringify(t));
  const tweak = t => { let c = t; while (r.bool(0.7)) { const k = r.bool() ? "L" : "R"; if (!c[k]) break; c = c[k]; } if (r.bool()) c.v = c.v === 1 ? 2 : 1; else put(c, nd(c.v), 0.5); return t; };
  // values that also catch serializations without separators (1 vs 12 vs 21)
  const V = big ? () => r.int(0, 1) : () => r.pick([1, 1, 2, 2, 12, 21]);
  const root = big ? deep(r.int(100, 300), 2000, V) : rnd(r.int(1, 9), V, r.pick([0.5, 0.2, 0.8]));
  let c = root;
  if (big) { while (size(c) > 1000) c = c.L && c.R ? (r.bool() ? c.L : c.R) : (c.L || c.R); }
  else { while (r.bool(0.6)) { const k = r.bool() ? "L" : "R"; if (!c[k]) break; c = c[k]; } }
  const mode = r.int(0, 3);
  const sub = mode <= 1 ? copy(c) : mode === 2 ? tweak(copy(c)) : rnd(r.int(1, big ? 1000 : 3), V, 0.5);
  return [ser(root), ser(sub)];
}

