function hasSubtree(root: TreeNode | null, sub: TreeNode | null): boolean {
  const same = (x: TreeNode | null, y: TreeNode | null): boolean => {
    if (!x || !y) return x === y; // both null, or a shape mismatch
    return x.val === y.val && same(x.left, y.left) && same(x.right, y.right);
  };
  const stack: (TreeNode | null)[] = [root];
  while (stack.length) {
    const node = stack.pop();
    if (!node) continue;
    if (same(node, sub)) return true;
    stack.push(node.left, node.right);
  }
  return false;
}

