            if not x or not y:
                return x is y  # both None, or a shape mismatch
            return x.val == y.val and same(x.left, y.left) and same(x.right, y.right)

        stack = [root]
        while stack:
            node = stack.pop()
            if node:
                if same(node, sub):
                    return True
                stack.extend((node.left, node.right))
        return False

