function hasSubtree(root: TreeNode | null, sub: TreeNode | null): boolean {
  const ser = (t: TreeNode | null): string => {
    const parts: string[] = [];
    const stack: (TreeNode | null)[] = [t];
    while (stack.length) {
      const n = stack.pop()!;
      if (!n) { parts.push(",#"); continue; }
      parts.push("," + n.val); // leading comma: ",2" can't match inside ",12"
      stack.push(n.right, n.left); // left comes out first: pre-order
    }
    return parts.join("");
  };
  return ser(root).includes(ser(sub));
}

